<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
import {segments,bounds,gaps,values,unknownLabel} from './marginChecker'
import type {Checker,Detail,Mode,Point,Stock} from './marginChecker'
const props=defineProps<{asOf?:string}>()
const info=ref<Checker|null>(null),detail=ref<Detail|null>(null),selected=ref('1815'),mode=ref<Mode>('net'),period=ref('90'),error=ref(''),loading=ref(false),hover=ref<number|null>(null),pinned=ref<string|null>(null),scrollArea=ref<HTMLDivElement|null>(null),viewportWidth=ref(900)
let seq=0,disposed=false,observer:ResizeObserver|undefined
const fmt=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:d})
const percent=(v:number|null|undefined)=>v==null?'—':fmt(v,1)+'%'
const points=computed(()=>{const all=detail.value?.points||[];return period.value==='all'?all:all.slice(-Number(period.value))})
const dates=computed(()=>{const all=info.value?.calendar||[];return period.value==='all'?all:all.slice(-Number(period.value))})
const width=computed(()=>Math.max(880,viewportWidth.value,points.value.length*5))
const left=65,right=35,priceTop=36,priceBottom=247,volumeTop=290,volumeBottom=370,unknownTop=424,unknownBottom=510
const x=(i:number)=>points.value.length<=1?(left+width.value-right)/2:left+i/(points.value.length-1)*(width.value-left-right)
const a=computed(()=>values(points.value,mode.value,'average')),f=computed(()=>values(points.value,mode.value,'fifo')),close=computed(()=>values(points.value,mode.value,'close'))
const ua=computed(()=>values(points.value,mode.value,'unknownAverage')),uf=computed(()=>values(points.value,mode.value,'unknownFifo'))
const range=computed(()=>bounds([...close.value,...a.value,...f.value]))
const py=(v:number)=>priceBottom-(v-range.value[0])/(range.value[1]-range.value[0])*(priceBottom-priceTop)
const maxVolume=computed(()=>Math.max(1,...points.value.map(p=>p?.balance||0)))
const vy=(v:number)=>volumeBottom-v/maxVolume.value*(volumeBottom-volumeTop)
const uy=(v:number)=>unknownBottom-v/100*(unknownBottom-unknownTop)
const resets=computed(()=>points.value.map(p=>!!p?.reset_reasons.length))
const pricePaths=computed(()=>segments(close.value,x,py)),averagePaths=computed(()=>segments(a.value,x,py,resets.value)),fifoPaths=computed(()=>segments(f.value,x,py,resets.value))
const unknownAveragePaths=computed(()=>segments(ua.value,x,uy,resets.value)),unknownFifoPaths=computed(()=>segments(uf.value,x,uy,resets.value))
const missing=computed(()=>gaps(points.value)),resetEvents=computed(()=>(detail.value?.points||[]).filter((p):p is Point=>p!==null&&p.reset_reasons.length>0))
const pinnedIndex=computed(()=>pinned.value?dates.value.indexOf(pinned.value):-1)
const activeIndex=computed(()=>hover.value??(pinnedIndex.value>=0?pinnedIndex.value:Math.max(0,points.value.length-1)))
const active=computed(()=>points.value[activeIndex.value]||null),activeDate=computed(()=>dates.value[activeIndex.value]||'')
const activePair=computed(()=>active.value?.models[mode.value]),windowSourceDays=computed(()=>points.value.filter(p=>p!==null).length)
const dateTicks=computed(()=>[...new Set([0,Math.floor((points.value.length-1)/2),points.value.length-1])].filter(i=>i>=0))
const resetMarkers=computed(()=>points.value.map((p,i)=>({p,i})).filter(v=>v.p?.reset_reasons.length))
function remember(){try{localStorage.setItem('margin-checker.preferences.v1',JSON.stringify({symbol:selected.value,mode:mode.value,period:period.value}))}catch{}}
async function load(symbol?:string){
 const request=++seq;loading.value=true;error.value=''
 try{const response=await localFetch('/api/margin-statistics/checker?'+new URLSearchParams({...symbol?{symbol}:{},...props.asOf?{date:props.asOf}:{}}));const value=await readJson<Checker&{error?:string}>(response);if(!response.ok)throw Error(value.error||'讀取檢查圖失敗');if(request!==seq||disposed)return
  info.value=value
  if(value.status==='missing'){detail.value=null;return}
  if(!symbol){if(!value.stocks.some(s=>s.symbol===selected.value))selected.value=value.stocks.find(s=>s.days===s.expected_days)?.symbol||value.stocks[0]?.symbol||'';await load(selected.value);return}
  detail.value=value.detail;hover.value=null;pinned.value=null;remember();await nextTick();if(scrollArea.value){observer?.disconnect();observer?.observe(scrollArea.value);viewportWidth.value=scrollArea.value.clientWidth;scrollArea.value.scrollLeft=scrollArea.value.scrollWidth}
 }catch(e){if(request===seq&&!disposed)error.value=e instanceof Error?e.message:String(e)}
 finally{if(request===seq&&!disposed)loading.value=false}
}
function choose(stock:Stock){if(loading.value&&stock.symbol===selected.value)return;selected.value=stock.symbol;load(stock.symbol)}
async function inspectDate(date:string){if(!info.value?.calendar.includes(date))return;if(!dates.value.includes(date))period.value='all';await nextTick();pinned.value=date;hover.value=null;await nextTick();const i=dates.value.indexOf(date);if(scrollArea.value)scrollArea.value.scrollLeft=Math.max(0,x(i)-scrollArea.value.clientWidth/2)}
function move(event:PointerEvent){const rect=(event.currentTarget as SVGElement).getBoundingClientRect();const pos=(event.clientX-rect.left)/rect.width*width.value;hover.value=Math.max(0,Math.min(points.value.length-1,Math.round((pos-left)/(width.value-left-right)*Math.max(0,points.value.length-1))))}
function mini(stock:Stock,field:'close'|'average'|'fifo'){
 const pts=stock.mini,nums=values(pts,mode.value,field),[lo,hi]=bounds([...values(pts,mode.value,'close'),...values(pts,mode.value,'average'),...values(pts,mode.value,'fifo')]);return segments(nums,i=>5+i/Math.max(1,pts.length-1)*170,v=>45-(v-lo)/(hi-lo)*38,field==='close'?[]:pts.map(p=>!!p?.reset_reasons.length))
}
function latestPair(stock:Stock){return stock.latest?.models[mode.value]}
watch([mode,period],()=>{hover.value=null;pinned.value=null;remember();nextTick(()=>{if(scrollArea.value)scrollArea.value.scrollLeft=scrollArea.value.scrollWidth})})
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('margin-checker.preferences.v1')||'{}');if(typeof p.symbol==='string')selected.value=p.symbol;if(p.mode==='replacement')mode.value=p.mode;if(['30','90','239','all'].includes(p.period))period.value=p.period}catch{}
 observer=new ResizeObserver(entries=>{const w=entries[0]?.contentRect.width;if(w&&Math.abs(w-viewportWidth.value)>1)viewportWidth.value=w});load()
})
watch(()=>props.asOf,()=>load(selected.value))
onUnmounted(()=>{disposed=true;seq++;observer?.disconnect()})
</script>
<template>
 <section class="checker" aria-label="包2A十檔圖像檢查">
  <div class="heading"><div><div class="eyebrow">PACKAGE 2A · TEN FIXED SAMPLES</div><h2>10檔個股 · 成本重建檢查</h2><p>把股價、兩種等值成本與未知存量放在一起，檢查模型是否合理。</p></div><span class="status">診斷用途 · 模型未通過</span></div>
  <p class="notice">成本線使用固定六成融資假設，並非實際買進均價；不作為支撐、目標價或交易訊號。</p>
  <p v-if="error" class="error" role="alert">{{error}} <button @click="load(selected)">重新讀取</button></p>
  <p v-if="info?.status==='missing'" class="notice">檢查圖資料尚未保存，讀取本頁不會自行重算模型。</p>
  <template v-else-if="info?.stocks.length">
   <div class="controls"><div class="segmented" role="group" aria-label="重建流量假設"><button :class="{chosen:mode==='net'}" :aria-pressed="mode==='net'" @click="mode='net'">淨變動</button><button :class="{chosen:mode==='replacement'}" :aria-pressed="mode==='replacement'" @click="mode='replacement'">換手情境</button></div><label>顯示期間<select v-model="period" aria-label="個股檢查期間"><option value="30">近30個交易日</option><option value="90">近90個交易日</option><option value="239">近239個交易日</option><option value="all">全期間 · {{info.calendar.length}}日</option></select></label><small>名單於 {{info.selection_frozen_at.slice(0,16).replace('T',' ')}} 固定，沒有按結果換股。</small></div>
   <div class="stock-grid" role="group" aria-label="固定10檔檢查名單">
    <button v-for="stock in info.stocks" :key="stock.symbol" class="stock-card" :class="{selected:selected===stock.symbol}" :aria-pressed="selected===stock.symbol" :aria-label="`檢查${stock.name}${stock.symbol}`" :data-checker-symbol="stock.symbol" @click="choose(stock)"><div class="stock-title"><b>{{stock.name}}</b><small>{{stock.market==='TWSE'?'上市':'上櫃'}}</small></div><span class="stock-code">{{stock.symbol}} · {{stock.days}} / {{stock.expected_days}}日</span><svg viewBox="0 0 180 50" aria-hidden="true"><path v-for="(p,i) in mini(stock,'close')" :key="'c'+i" :d="p" class="price-line"/><path v-for="(p,i) in mini(stock,'average')" :key="'a'+i" :d="p" class="average-line"/><path v-for="(p,i) in mini(stock,'fifo')" :key="'f'+i" :d="p" class="fifo-line"/></svg><span class="stock-price">收盤 {{fmt(stock.latest?.close)}}</span><small class="stock-unknown">未知存量：平均 {{percent(latestPair(stock)?.average.unknown_pct)}} / FIFO {{percent(latestPair(stock)?.fifo.unknown_pct)}}</small><small v-if="stock.days<stock.expected_days" class="missing-label">歷史不足，保留空白區間</small></button>
   </div>
   <div v-if="detail" class="detail" :class="{loading}">
    <div class="detail-heading"><h3>{{detail.name}} <span>{{detail.symbol}} · {{detail.market==='TWSE'?'上市':'上櫃'}}</span></h3><div class="date-controls"><label>定位交易日<select :value="activeDate" aria-label="定位檢查交易日" @change="inspectDate(($event.target as HTMLSelectElement).value)"><option v-for="d in [...info.calendar].reverse()" :key="d" :value="d">{{d}}</option></select></label><button v-if="pinned" @click="pinned=null;hover=null;scrollArea?.scrollTo({left:scrollArea.scrollWidth})">回到最新</button></div></div>
    <p class="coverage">融資來源 {{detail.days}} / {{detail.expected_days}}日 · 本視窗 {{windowSourceDays}} / {{points.length}}日 · {{dates[0]}} ～ {{dates.at(-1)}}</p>
    <p v-if="detail.days<detail.expected_days" class="notice warning">本檔只有 {{detail.days}} 日可重建資料。灰色區段是缺漏，不補值、不跨缺口連線。</p>
    <div class="readings" :data-checker-date="activeDate"><article><small>{{hover!=null?'游標日期':pinned?'定位日期':'最新交易日'}}</small><strong>{{activeDate}}</strong><span>{{active===null?'缺融資來源':active.balance===0?'無融資部位':active.reset_reasons.length?'本日有重設':'已有來源，仍屬診斷'}}</span></article><article><small>收盤／融資餘額</small><strong>{{fmt(active?.close)}} <em>元</em></strong><span>{{active===null?'餘額未知':fmt(active.balance,0)+' 張'}}</span></article><article><small>平均法等值成本／未知存量</small><strong>{{fmt(activePair?.average.cost)}} <em>元</em></strong><span :class="{warning:(activePair?.average.unknown_pct||0)>10}">{{percent(activePair?.average.unknown_pct)}} · {{unknownLabel(activePair?.average.unknown_pct)}}</span></article><article><small>FIFO等值成本／未知存量</small><strong>{{fmt(activePair?.fifo.cost)}} <em>元</em></strong><span :class="{warning:(activePair?.fifo.unknown_pct||0)>10}">{{percent(activePair?.fifo.unknown_pct)}} · {{unknownLabel(activePair?.fifo.unknown_pct)}}</span></article></div>
    <div class="legend"><span><i class="price"></i>收盤價</span><span><i class="avg"></i>平均法等值成本</span><span><i class="fifo"></i>FIFO等值成本</span><span><i class="reset"></i>重設／待核對</span><span><i class="gap"></i>缺融資來源</span></div>
    <p class="scroll-hint">下方可正常左右捲動；游標移到某日會同步顯示三個圖與上方數值，移開回到最新或定位日。</p>
    <div ref="scrollArea" class="chart-scroll" tabindex="0" aria-label="個股成本、融資餘額與未知存量圖，可左右捲動">
     <svg :width="width" height="555" :viewBox="`0 0 ${width} 555`" role="img" :aria-label="`${detail.name}三組檢查圖，${points.length}個交易日`" @pointermove="move" @pointerleave="hover=null">
      <defs><pattern id="checker-missing-hatch" patternUnits="userSpaceOnUse" width="8" height="8"><path d="M0 8L8 0" stroke="#e3e7e4" stroke-width="1"/></pattern></defs>
      <rect :width="width" height="555" fill="white"/>
      <g v-for="gap in missing" :key="gap.start"><rect :x="Math.max(left,x(gap.start)-2)" :width="Math.max(4,Math.min(width-right,x(gap.end)+2)-Math.max(left,x(gap.start)-2))" y="25" height="485" fill="url(#checker-missing-hatch)"/><title>缺融資來源 {{dates[gap.start]}} ～ {{dates[gap.end]}}，{{gap.count}}日</title></g>
      <text x="12" y="17" class="axis-title">股價／等值成本（元）</text>
      <g v-for="tick in [range[0],(range[0]+range[1])/2,range[1]]" :key="tick"><line :x1="left" :x2="width-right" :y1="py(tick)" :y2="py(tick)" class="grid-line"/><text :x="left-8" :y="py(tick)+4" text-anchor="end" class="tick">{{fmt(tick)}}</text></g>
      <g v-for="mark in resetMarkers" :key="mark.i"><line :x1="x(mark.i)" :x2="x(mark.i)" :y1="priceTop" :y2="priceBottom" class="reset-line"/><path :d="`M${x(mark.i)-4},27 L${x(mark.i)+4},27 L${x(mark.i)},34 Z`" fill="#bd974b"/><title>{{mark.p?.date}}：{{mark.p?.reset_labels.join('；')}}</title></g>
      <path v-for="(p,i) in pricePaths" :key="'p'+i" :d="p" class="price-line"/><path v-for="(p,i) in averagePaths" :key="'a'+i" :d="p" class="average-line"/><path v-for="(p,i) in fifoPaths" :key="'f'+i" :d="p" class="fifo-line"/>
      <text x="12" y="277" class="axis-title">融資餘額（張）</text><line :x1="left" :x2="width-right" :y1="volumeBottom" :y2="volumeBottom" class="grid-line"/><text :x="left-8" :y="volumeTop+4" text-anchor="end" class="tick">{{fmt(maxVolume,0)}}</text><text :x="left-8" :y="volumeBottom+4" text-anchor="end" class="tick">0</text>
      <g v-for="(point,i) in points" :key="i"><rect v-if="point!==null&&point.balance>0" :x="x(i)-Math.min(4,(width-left-right)/Math.max(1,points.length)*.65)/2" :width="Math.min(4,(width-left-right)/Math.max(1,points.length)*.65)" :y="vy(point.balance)" :height="volumeBottom-vy(point.balance)" fill="#9bb1bd"/></g>
      <text x="12" y="410" class="axis-title">未知存量占餘額（%）</text><rect :x="left" :y="uy(10)" :width="width-left-right" :height="unknownBottom-uy(10)" fill="#f0f5ed"/><g v-for="tick in [0,50,100]" :key="tick"><line :x1="left" :x2="width-right" :y1="uy(tick)" :y2="uy(tick)" class="grid-line"/><text :x="left-8" :y="uy(tick)+4" text-anchor="end" class="tick">{{tick}}%</text></g><line :x1="left" :x2="width-right" :y1="uy(10)" :y2="uy(10)" stroke="#b99243" stroke-dasharray="4 4"/><text :x="width-right-4" :y="uy(10)-4" text-anchor="end" class="threshold-label">10%參考線 · 單項條件</text><path v-for="(p,i) in unknownAveragePaths" :key="'ua'+i" :d="p" class="average-line"/><path v-for="(p,i) in unknownFifoPaths" :key="'uf'+i" :d="p" class="fifo-line"/>
      <line v-if="points.length" :x1="x(activeIndex)" :x2="x(activeIndex)" y1="28" y2="510" stroke="#748e7b" stroke-dasharray="3 3"/>
      <g v-if="active"><circle v-if="active.close!=null" :cx="x(activeIndex)" :cy="py(active.close)" r="3" fill="#bd6655"/><circle v-if="activePair?.average.cost!=null" :cx="x(activeIndex)" :cy="py(activePair.average.cost)" r="3" fill="#547a62"/><circle v-if="activePair?.fifo.cost!=null" :cx="x(activeIndex)" :cy="py(activePair.fifo.cost)" r="3" fill="#8e6ab2"/></g>
      <text v-for="i in dateTicks" :key="i" :x="x(i)" y="541" :text-anchor="i===0?'start':i===points.length-1?'end':'middle'" class="tick">{{dates[i]}}</text>
     </svg>
    </div>
    <div class="day-notes"><b>{{activeDate}}</b><span v-if="active?.reset_labels.length">{{active.reset_labels.join('；')}}。等值成本與未知存量線在此斷開，避免假裝連續。</span><span v-else-if="active===null">本日缺融資來源，所有重建數值保留空白。</span><span v-else>未標示重設，也不代表估計成本已核實。{{activePair?.average.cap_unknown_units||activePair?.fifo.cap_unknown_units?'仍有部位的融資成數待核對。':''}}</span></div>
    <details class="events"><summary>檢視 {{detail.reset_days}} 個起始／重設日</summary><p>這是模型重設標記，原因尚未逐筆確認；不能直接解讀成主力買賣或成本清洗。</p><div class="event-scroll"><div v-for="e in resetEvents" :key="e.date"><button @click="inspectDate(e.date)">{{e.date}}</button><span>{{e.reset_labels.join('；')}}</span></div></div></details>
    <details class="method"><summary>如何閱讀這張檢查圖</summary><p>{{info.cost_definition}}</p><p>{{info.unknown_definition}}</p><p>淨變動只更新每日餘額差；換手情境容許同日先退舊部位再建新部位。兩者都符合相同每日淨餘額，卻可能得到不同成本與未知存量。</p><p>灰色區段不補值；沒有融資部位時不畫成本及未知比例。模型重設時，保留實際股價，但斷開推估線。這些資料是包2封存來源的回溯版本，不能視為當年即時可得。</p></details>
   </div>
  </template><p v-if="loading" class="load-state" role="status">正在讀取封存檢查資料…</p>
 </section>
</template>
